public class Main {
    static int[] parent;
    static int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        int n = Integer.parseInt(line.trim());
        long[][] jobs = new long[n][2];
        StringTokenizer st = null;
        for (int i = 0; i < n; i++) {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            jobs[i][0] = Long.parseLong(st.nextToken());
            jobs[i][1] = Long.parseLong(st.nextToken());
        }
        Arrays.sort(jobs, (a, b) -> Long.compare(b[1], a[1]));
        parent = new int[n + 1];
        for (int i = 0; i <= n; i++) parent[i] = i;
        int count = 0;
        long totalProfit = 0;
        for (int i = 0; i < n; i++) {
            int d = (int) Math.min(n, jobs[i][0]);
            int available = find(d);
            if (available > 0) {
                count++;
                totalProfit += jobs[i][1];
                parent[available] = find(available - 1);
            }
        }
        System.out.println(count + " " + totalProfit);
    }
}

