#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        for (int i = 0; i <= n; i++) parent[i] = i;
    }
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    void unite(int u, int v) {
        parent[u] = v;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<pair<long long, int>> jobs(n);
    for (int i = 0; i < n; i++) {
        int d;
        long long p;
        cin >> d >> p;
        jobs[i] = {p, d};
    }
    sort(jobs.rbegin(), jobs.rend());
    DSU dsu(n);
    int count = 0;
    long long totalProfit = 0;
    for (int i = 0; i < n; i++) {
        int d = min(n, jobs[i].second);
        int available = dsu.find(d);
        if (available > 0) {
            count++;
            totalProfit += jobs[i].first;
            dsu.unite(available, dsu.find(available - 1));
        }
    }
    cout << count << ' ' << totalProfit << "\n";
    return 0;
}

