import java.io.*;
import java.util.*;

public class Main {
    static class Node implements Comparable<Node> {
        char ch;
        long freq;
        int order;
        Node left, right;
        Node(char c, long f, int o) { this.ch = c; this.freq = f; this.order = o; }
        public int compareTo(Node o) {
            if (this.freq != o.freq) return Long.compare(this.freq, o.freq);
            return Integer.compare(this.order, o.order);
        }
    }
    static void preorder(Node node, String code, List<String> res) {
        if (node == null) return;
        if (node.left == null && node.right == null) {
            res.add(code.isEmpty() ? "0" : code);
            return;
        }
        preorder(node.left, code + "0", res);
        preorder(node.right, code + "1", res);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null || s.trim().isEmpty()) return;
        s = s.trim();
        String line2 = br.readLine();
        if (line2 == null || line2.trim().isEmpty()) return;
        String[] tokens = line2.trim().split("\\s+");
        int n = s.length();
        if (n == 1) { System.out.println("0"); return; }
        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            pq.add(new Node(s.charAt(i), Long.parseLong(tokens[i]), i));
        }
        int order = n;
        while (pq.size() > 1) {
            Node l = pq.poll();
            Node r = pq.poll();
            Node p = new Node('$', l.freq + r.freq, order++);
            p.left = l; p.right = r;
            pq.add(p);
        }
        List<String> codes = new ArrayList<>();
        preorder(pq.peek(), "", codes);
        System.out.println(String.join(" ", codes));
    }
}

