#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <queue>
using namespace std;

struct Node {
    char ch;
    long long freq;
    int order;
    Node *left = nullptr, *right = nullptr;
    Node(char c, long long f, int o) : ch(c), freq(f), order(o) {}
};

struct Compare {
    bool operator()(Node* a, Node* b) {
        if (a->freq != b->freq) return a->freq > b->freq;
        return a->order > b->order;
    }
};

void preorder(Node* node, string code, vector<string>& res) {
    if (!node) return;
    if (!node->left && !node->right) {
        res.push_back(code.empty() ? "0" : code);
        return;
    }
    preorder(node->left, code + "0", res);
    preorder(node->right, code + "1", res);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s;
    if (!getline(cin, s) || s.empty()) return 0;
    string line;
    if (!getline(cin, line) || line.empty()) return 0;
    stringstream ss(line);
    int n = s.size();
    if (n == 1) { cout << "0\n"; return 0; }
    priority_queue<Node*, vector<Node*>, Compare> pq;
    for (int i = 0; i < n; i++) {
        long long f;
        ss >> f;
        pq.push(new Node(s[i], f, i));
    }
    int order = n;
    while (pq.size() > 1) {
        Node* l = pq.top(); pq.pop();
        Node* r = pq.top(); pq.pop();
        Node* p = new Node('$', l->freq + r->freq, order++);
        p->left = l; p->right = r;
        pq.push(p);
    }
    vector<string> codes;
    preorder(pq.top(), "", codes);
    for (size_t i = 0; i < codes.size(); i++) {
        if (i > 0) cout << ' ';
        cout << codes[i];
    }
    cout << "\n";
    return 0;
}

