import java.io.*;
import java.util.*;

public class Main {
    static class Item {
        double v, w, r;
        Item(double v, double w) { this.v = v; this.w = w; this.r = v / w; }
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        StringTokenizer st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        double cap = Double.parseDouble(st.nextToken());
        Item[] items = new Item[n];
        for (int i = 0; i < n; i++) {
            while (!st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            double v = Double.parseDouble(st.nextToken());
            double w = Double.parseDouble(st.nextToken());
            items[i] = new Item(v, w);
        }
        Arrays.sort(items, (a, b) -> Double.compare(b.r, a.r));
        double total = 0.0;
        double rem = cap;
        for (Item it : items) {
            if (rem <= 0) break;
            double take = Math.min(rem, it.w);
            total += take * it.r;
            rem -= take;
        }
        System.out.printf(Locale.US, "%.2f\n", total);
    }
}

