        Arrays.sort(arr);
        Arrays.sort(dep);
        int platNeeded = 0, maxPlat = 0;
        int i = 0, j = 0;
        while (i < n && j < n) {
            if (arr[i] <= dep[j]) {
                platNeeded++;
                maxPlat = Math.max(maxPlat, platNeeded);
                i++;
            } else {
                platNeeded--;
                j++;
            }
        }
        System.out.println(maxPlat);
    }
}

