                if (net[i] > net[maxCreditor]) maxCreditor = i;
                if (net[i] < net[maxDebtor]) maxDebtor = i;
            }
            if (net[maxCreditor] == 0 && net[maxDebtor] == 0) break;
            long settle = Math.min(-net[maxDebtor], net[maxCreditor]);
            net[maxDebtor] += settle;
            net[maxCreditor] -= settle;
