            pq.add(Long.parseLong(st.nextToken()));
        }

        if (N <= 1) {
            System.out.println(0);
            return;
        }

        long totalCost = 0;
        while (pq.size() > 1) {
            long a = pq.poll();
            long b = pq.poll();
            long sum = a + b;
            totalCost += sum;
            pq.add(sum);
        }
        System.out.println(totalCost);
    }
}

