import sys

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    S = int(raw[0])
    D = int(raw[1])

    if S == 0:
        if D == 1:
            print(0)
        else:
            print(-1)
        return

    if S > 9 * D:
        print(-1)
        return

    # Reserve 1 for the most significant digit
    rem_sum = S - 1
    digits = [0] * D

    # Fill from least significant (right) to second digit (left)
    for i in range(D - 1, 0, -1):
        if rem_sum >= 9:
            digits[i] = 9
            rem_sum -= 9
        else:
            digits[i] = rem_sum
            rem_sum = 0

    # The first digit gets 1 + remaining sum
    digits[0] = 1 + rem_sum
    print(''.join(map(str, digits)))

if __name__ == '__main__':
    solve()

