import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNext()) return;
        String S = sc.next();
        int N = S.length();

        int[] freq = new int[26];
        int maxFreq = 0;
        for (char c : S.toCharArray()) {
            freq[c - 'a']++;
            if (freq[c - 'a'] > maxFreq) maxFreq = freq[c - 'a'];
        }

        if (maxFreq > (N + 1) / 2) {
            System.out.println("-1");
            return;
        }

        Integer[] order = new Integer[26];
        for (int i = 0; i < 26; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(freq[b], freq[a]));

        char[] res = new char[N];
        int idx = 0;
        for (int chIdx : order) {
            char c = (char) ('a' + chIdx);
            int count = freq[chIdx];
            for (int k = 0; k < count; k++) {
                res[idx] = c;
                idx += 2;
                if (idx >= N) idx = 1;
            }
        }
        System.out.println(new String(res));
    }
}

